import { createHash, randomBytes } from "node:crypto";
import type { PrivateKeyAccount } from "viem/accounts";
import type { PreferencePair } from "../../domain/evaluation/preference-pair.js";

const SEPOLIA_CHAIN_ID = 11155111;

export interface Provenance {
  /** e.g. "synthetic": material generated by a program rather than collected from a public source. */
  readonly sourceKind: string;
  readonly sourceUrl?: string;
}

/** One NDJSON line in the format the Telegraph evaluation pool accepts. */
export function toEvalPoolLine(pair: PreferencePair, intentId: string, provenance: Provenance): string {
  return JSON.stringify({
    prompt: pair.question,
    chosen: pair.preferred,
    rejected: pair.rejected,
    label_kind: "preference_pair",
    intent_id: intentId,
    provenance: { source_kind: provenance.sourceKind, ...(provenance.sourceUrl ? { source_url: provenance.sourceUrl } : {}) },
  });
}

export interface RowStatus {
  readonly status: string;
  readonly reason_code?: string;
  readonly row_hash?: string;
  readonly case_id?: string;
}

/** Uploads evaluation material to a Telegraph node, signed by the contributor's wallet (EIP-191). */
export class EvalPoolClient {
  constructor(
    private readonly nodeUrl: string,
    private readonly account: PrivateKeyAccount,
  ) {}

  async submit(intentId: string, ndjson: string): Promise<{ httpStatus: number; body: string }> {
    const body = Buffer.from(ndjson, "utf8");
    const nonce = randomBytes(16).toString("hex");
    // The node rebuilds this exact five-line message to check the signature.
    const message = [
      "Telegraph eval-pool submission v1",
      `intent_id: ${intentId}`,
      `body_sha256: ${createHash("sha256").update(body).digest("hex")}`,
      `nonce: ${nonce}`,
      `chain_id: ${SEPOLIA_CHAIN_ID}`,
    ].join("\n");
    const signature = await this.account.signMessage({ message });
    const url = `${this.nodeUrl}/api/evalpool/submissions?intent_id=${encodeURIComponent(intentId)}&submitter=${this.account.address}`;
    const response = await fetch(url, {
      method: "POST",
      headers: { "Content-Type": "application/x-ndjson", "X-Evalpool-Signature": signature, "X-Evalpool-Nonce": nonce },
      body,
    });
    return { httpStatus: response.status, body: await response.text() };
  }

  async myRows(intentId: string): Promise<RowStatus[]> {
    const url = `${this.nodeUrl}/api/evalpool/submissions/mine?submitter=${this.account.address}&intent_id=${encodeURIComponent(intentId)}&limit=5000`;
    const response = await fetch(url);
    if (!response.ok) throw new Error(`Could not read submitted rows: HTTP ${response.status} ${await response.text()}`);
    const body = (await response.json()) as { rows?: RowStatus[] } | RowStatus[];
    return Array.isArray(body) ? body : (body.rows ?? []);
  }
}
